import sys

def insert_brute(ints, newi):
    ints = sorted(ints + [newi])
    res = []
    for s, e in ints:
        if res and s <= res[-1][1]:
            res[-1][1] = max(res[-1][1], e)
        else:
            res.append([s, e])
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    ints = []
    idx = 1
    for _ in range(n):
        ints.append([int(data[idx]), int(data[idx + 1])])
        idx += 2
    newi = [int(data[idx]), int(data[idx + 1])]
    res = insert_brute(ints, newi)
    for s, e in res:
        print(s, e)
